// Generated by support-ops call-concurrency/web/build.py from docs.template.jsx and model.js.
// Don't edit here: edit those, then run python call-concurrency/web/build.py --docs <ultradox>.

export const ConcurrencyPlanner = () => {
  // Call concurrency math for Ultravox planning: a line-for-line port of ../model.py.
  // Checked against vectors.json (generated from model.py) by tests/test_web.py.
  // The standalone page, the docs calculator and the console page all copy this file.

  const WEEKS_PER_MONTH = 365.25 / 7 / 12;
  const TARGETS = [0.95, 0.99, 0.999];
  const DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

  function loadErlangs(callsPerHour, avgMinutes) {
    return (callsPerHour * avgMinutes) / 60;
  }

  // --- Priority slots: Poisson -------------------------------------------------

  const LOG_FACTORIAL = [0];
  for (let k = 1; k <= 30; k++) LOG_FACTORIAL[k] = LOG_FACTORIAL[k - 1] + Math.log(k);

  function logFactorial(n) {
    if (n <= 30) return LOG_FACTORIAL[n];
    // Stirling's series; error is far below 1e-15 relative for n > 30.
    const n2 = n * n;
    return n * Math.log(n) - n + 0.5 * Math.log(2 * Math.PI * n) + 1 / (12 * n) - 1 / (360 * n * n2) + 1 / (1260 * n2 * n2 * n);
  }

  function logPmf(load, k) {
    return k * Math.log(load) - load - logFactorial(k);
  }

  // Share of calls that start while `slots` or more calls are already active.
  function promiseOverflow(load, slots) {
    if (slots <= 0) return 1;
    if (load <= 0) return 0;
    if (slots > load) {
      let total = 0;
      for (let k = slots; ; k++) {
        const term = Math.exp(logPmf(load, k));
        total += term;
        if (term === 0 || term < total * 1e-15) return total;
      }
    }
    let below = 0;
    for (let k = slots - 1; k >= 0; k--) {
      const term = Math.exp(logPmf(load, k));
      below += term;
      if (term === 0 || term < below * 1e-15) break;
    }
    return Math.max(0, 1 - below);
  }

  // --- Hard caps: Erlang B -----------------------------------------------------

  // Share of calls rejected by a hard cap of `slots` (no retries).
  function erlangB(load, slots) {
    let b = 1;
    for (let k = 1; k <= slots; k++) b = (load * b) / (k + load * b);
    return b;
  }

  // --- Bursty arrivals: negative binomial ---------------------------------------

  // Log-gamma (Lanczos, g = 7), for the negative binomial's non-integer shape.
  function lgamma(z) {
    const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313, -176.61502916214059,
      12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
    if (z < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i < 9; i++) x += c[i] / (z + i);
    const t = z + 7.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }

  function nbLogPmf(load, burst, k) {
    const r = load / (burst - 1), p = 1 / burst;
    return lgamma(k + r) - logFactorial(k) - lgamma(r) + r * Math.log(p) + k * Math.log1p(-p);
  }

  // P(N >= m) for a negative binomial with mean `load` and variance `burst` * `load`.
  function nbTail(load, burst, m) {
    if (m <= 0) return 1;
    if (m > load) {
      let total = 0;
      for (let k = m; ; k++) {
        const term = Math.exp(nbLogPmf(load, burst, k));
        total += term;
        if (term === 0 || term < total * 1e-15) return total;
      }
    }
    let below = 0;
    for (let k = m - 1; k >= 0; k--) {
      const term = Math.exp(nbLogPmf(load, burst, k));
      below += term;
      if (term === 0 || term < below * 1e-15) break;
    }
    return Math.max(0, 1 - below);
  }

  // Share of calls that start with all `slots` in use when calls come in bursts averaging `burst`
  // calls (geometric sizes, bursts at random, exponential lengths). See burst_overflow in model.py.
  function burstOverflow(load, slots, burst) {
    if (burst <= 1) return promiseOverflow(load, slots);
    if (slots <= 0) return 1;
    if (load <= 0) return 0;
    const q = 1 - 1 / burst;
    let tail = nbTail(load, burst, slots);
    let total = 0;
    let weight = 1 / burst;
    for (let m = slots; m > 0; m--) {
      total += weight * Math.min(1, tail);
      weight *= q;
      if (weight < 1e-17) return total;
      tail += Math.exp(nbLogPmf(load, burst, m - 1));
    }
    return total + weight * burst;
  }

  // Solve a x = b by Gaussian elimination with partial pivoting (small systems only).
  function solve(a, b) {
    const n = b.length;
    const m = a.map((row, i) => [...row, b[i]]);
    for (let c = 0; c < n; c++) {
      let p = c;
      for (let r = c + 1; r < n; r++) if (Math.abs(m[r][c]) > Math.abs(m[p][c])) p = r;
      [m[c], m[p]] = [m[p], m[c]];
      for (let r = 0; r < n; r++) {
        if (r === c || !m[r][c]) continue;
        const f = m[r][c] / m[c][c];
        for (let k = c; k <= n; k++) m[r][k] -= f * m[c][k];
      }
    }
    return m.map((row, i) => row[n] / row[i]);
  }

  // Share of calls rejected by a hard cap of `cap` when calls come in bursts averaging `burst`.
  // Erlang B when burst <= 1; see cap_overflow in model.py.
  function capOverflow(load, cap, burst = 1) {
    if (burst <= 1) return erlangB(load, cap);
    if (cap <= 0) return 1;
    if (load <= 0) return 0;
    const q = 1 - 1 / burst, rate = load / burst, n = cap + 1;
    const gen = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
      if (i < cap) {
        for (let k = 1; k < cap - i; k++) gen[i][i + k] += rate * (1 - q) * q ** (k - 1);
        gen[i][cap] += rate * q ** (cap - i - 1);
      }
      if (i > 0) gen[i][i - 1] += i;
      gen[i][i] = -gen[i].reduce((s, x, j) => (j === i ? s : s + x), 0);
    }
    const a = Array.from({ length: n }, (_, r) => Array.from({ length: n }, (_, c) => gen[c][r]));
    a[n - 1] = new Array(n).fill(1);
    const pi = solve(a, [...new Array(n - 1).fill(0), 1]);
    return pi.reduce((s, p, i) => s + p * q ** (cap - i), 0);
  }

  const MODELS = { promise: promiseOverflow, cap: erlangB };

  function overflowFor(model, burst) {
    if (burst > 1) {
      const overflow = model === "promise" ? burstOverflow : capOverflow;
      return (load, slots) => overflow(load, slots, burst);
    }
    return MODELS[model];
  }

  // Fewest slots that keep at least `target` of calls inside the limit. `burst` > 1: calls come in
  // clusters of that many on average.
  function slotsNeeded(load, target, model = "promise", burst = 1) {
    const overflow = overflowFor(model, burst);
    const allowed = 1 - target;
    if (load <= 0) return 0;
    let lo = 0;
    let hi = Math.max(1, Math.ceil(load));
    while (overflow(load, hi) > allowed) {
      lo = hi;
      hi *= 2;
    }
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (overflow(load, mid) <= allowed) hi = mid;
      else lo = mid + 1;
    }
    return hi;
  }

  // Highest load (erlangs) that `slots` can carry with `target` of calls inside the limit.
  function loadCovered(slots, target, model = "promise", burst = 1) {
    if (slots <= 0) return 0;
    const overflow = overflowFor(model, burst);
    const allowed = 1 - target;
    let lo = 0;
    let hi = slots * 2 + 10;
    for (let i = 0; i < 100; i++) {
      const mid = (lo + hi) / 2;
      if (overflow(mid, slots) <= allowed) lo = mid;
      else hi = mid;
    }
    return lo;
  }

  // How a slot count compares with what Pro typically gets at once (no hard cap, not guaranteed):
  // "fits" up to the low end of `typical`, "tight" up to the high end, "over" beyond it.
  function proFit(slots, [low, high]) {
    return slots <= low ? "fits" : slots <= high ? "tight" : "over";
  }

  // --- Schedules ---------------------------------------------------------------

  function schedule(label, days, startHour, endHour) {
    const hoursPerDay = (((endHour - startHour) % 24) + 24) % 24 || 24;
    return { label, days, startHour, endHour, hoursPerDay, openHoursPerMonth: days.length * WEEKS_PER_MONTH * hoursPerDay };
  }

  const PRESETS = {
    "24x7": schedule("24/7", DAYS, 0, 0),
    weekdays: schedule("Mon-Fri 9am-5pm", DAYS.slice(0, 5), 9, 17),
  };

  function parseDays(spec) {
    const days = [];
    const index = (name) => {
      const i = DAYS.indexOf(name.slice(0, 3));
      if (i < 0) throw new Error("bad day");
      return i;
    };
    for (const part of spec.split(",")) {
      if (part.includes("-")) {
        const [a, b] = part.split("-", 2);
        const i = index(a);
        const j = index(b);
        for (let d = i; ; d = (d + 1) % 7) {
          days.push(DAYS[d]);
          if (d === j) break;
        }
      } else {
        days.push(DAYS[index(part)]);
      }
    }
    return [...new Set(days)];
  }

  // '24x7', 'weekdays', or custom like 'mon-sat 8-20'. Hours are local, end exclusive.
  function parseSchedule(spec) {
    const key = spec.trim().toLowerCase();
    if (PRESETS[key]) return PRESETS[key];
    const m = key.match(/^\s*([a-z,-]+)\s+(\d{1,2})-(\d{1,2})\s*$/);
    if (!m) throw new Error(`schedule ${JSON.stringify(spec)}: use 24x7, weekdays, or e.g. 'mon-fri 8-20'`);
    let days;
    try {
      days = parseDays(m[1]);
    } catch {
      throw new Error(`schedule ${JSON.stringify(spec)}: days are mon..sun, e.g. 'mon-fri' or 'sat,sun'`);
    }
    const start = Number(m[2]);
    const end = Number(m[3]);
    if (start > 24 || end > 24) throw new Error(`schedule ${JSON.stringify(spec)}: hours are 0-24`);
    return schedule(spec.trim(), days, start % 24, end % 24);
  }

  // Erlangs in the busiest hour: minutes spread over open hours, times `peak`.
  function busiestHourLoad(monthlyMinutes, sched, peak = 1) {
    return (monthlyMinutes / (sched.openHoursPerMonth * 60)) * peak;
  }

  function monthlyMinutesForLoad(load, sched, peak = 1) {
    return (load / peak) * sched.openHoursPerMonth * 60;
  }

  // --- Outbound lists ----------------------------------------------------------

  function listHours(calls, avgMinutes, slots) {
    if (slots <= 0) throw new Error("slots must be >= 1");
    return (calls * avgMinutes) / slots / 60;
  }

  function slotsForList(calls, avgMinutes, hours) {
    if (hours <= 0) throw new Error("hours must be > 0");
    return Math.ceil((calls * avgMinutes) / (hours * 60));
  }

  // --- Simulating a busy hour (JS only: a picture for the customer page) -------

  // Small seeded PRNG, so "Run again" can step through hours and tests are repeatable.
  function mulberry32(seed) {
    let a = seed >>> 0;
    return () => {
      a = (a + 0x6d2b79f5) >>> 0;
      let t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function poissonSample(mean, rand) {
    if (mean <= 0) return 0;
    if (mean > 50) {
      // Normal approximation; Box-Muller.
      const z = Math.sqrt(-2 * Math.log(1 - rand())) * Math.cos(2 * Math.PI * rand());
      return Math.max(0, Math.round(mean + Math.sqrt(mean) * z));
    }
    const limit = Math.exp(-mean);
    let k = 0;
    for (let p = rand(); p > limit; p *= rand()) k++;
    return k;
  }

  // One random busy hour, minute 0 to `minutes`: calls active every `step` minutes (`samples`), and
  // how many calls each arriving call found already active (`seen`, exact, for per-call checks).
  // Arrivals are random (Poisson) at `callsPerHour`, or with `burst` > 1, random bursts of a
  // geometric number of calls averaging `burst`. Call lengths are exponential with mean `avgMinutes`.
  // Samples are taken at moments rather than as each minute's peak, so the share of time above a level
  // matches the share of calls that find it (calls arriving at random see time averages).
  function simulateBusyHour(callsPerHour, avgMinutes, seed = 1, minutes = 60, step = 0.5, burst = 1) {
    const rand = mulberry32(seed);
    const exp = (mean) => -mean * Math.log(1 - rand());
    const perMinute = callsPerHour / 60;
    const events = [];
    let start = 0;
    if (burst > 1) {
      // Warm up for 10 average call lengths so the hour starts in steady state.
      start = -Math.min(10 * avgMinutes, 600);
      const q = 1 - 1 / burst;
      for (let t = start + exp(burst / perMinute); perMinute > 0 && t < minutes; t += exp(burst / perMinute)) {
        let size = 1;
        while (rand() < q) size++;
        for (let i = 0; i < size; i++) events.push([t, 1], [t + exp(avgMinutes), -1]);
      }
    } else {
      // Calls already running at minute 0: their remaining lengths are exponential too.
      const running = poissonSample(perMinute * avgMinutes, rand);
      for (let i = 0; i < running; i++) events.push([0, 1], [exp(avgMinutes), -1]);
      for (let t = exp(1 / perMinute); perMinute > 0 && t < minutes; t += exp(1 / perMinute)) {
        events.push([t, 1], [t + exp(avgMinutes), -1]);
      }
    }
    // Ends before starts at the same moment; a burst's calls keep their order.
    events.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
    const samples = [];
    const seen = [];
    let active = 0;
    let e = 0;
    const advance = (until, inclusive) => {
      for (; e < events.length && (inclusive ? events[e][0] <= until : events[e][0] < until); e++) {
        const [t, d] = events[e];
        if (d === 1 && t > 0) seen.push(active); // calls running at minute 0 aren't arrivals in the hour
        active += d;
      }
    };
    for (let i = 0; i < Math.round(minutes / step); i++) {
      advance(i * step, true);
      samples.push(active);
    }
    advance(minutes, false);
    return { samples, seen };
  }

  const DATA = {"payg_cap": 5, "pro_typical": [15, 25], "contact_sales": "https://inworld.ai/contact-sales?utm_source=ultravox&utm_medium=docs"};
  const CAP = DATA.payg_cap;
  const PRO = DATA.pro_typical; // what Pro typically gets at once; not guaranteed
  const SALES = DATA.contact_sales;
  const OCS_URL = "/telephony/outbound-call-scheduler";

  // --- state and inputs -------------------------------------------------------

  const RATE = { min: 1, max: 10000 };
  const LEN = { min: 0.5, max: 60 };
  const toSlider = (v, r) => Math.round((1000 * Math.log(Math.min(Math.max(v, r.min), r.max) / r.min)) / Math.log(r.max / r.min));
  const fromSlider = (x, r) => r.min * (r.max / r.min) ** (x / 1000);
  const tidyRate = (v) => (v < 100 ? Math.round(v) : Number(v.toPrecision(2)));
  const tidyLen = (v) => (v < 10 ? Math.round(v * 2) / 2 : Math.round(v));

  const [rate, setRate] = useState(300);
  const [len, setLen] = useState(3);
  const [rateText, setRateText] = useState("300");
  const [lenText, setLenText] = useState("3");
  const [seed, setSeed] = useState(1);
  const [hover, setHover] = useState(null);
  const [dark, setDark] = useState(false);
  const [width, setWidth] = useState(680);
  const chartBox = useRef(null);

  // Follow the docs' light/dark theme, which Mintlify sets as a class on <html>.
  useEffect(() => {
    const root = document.documentElement;
    const sync = () => setDark(root.classList.contains("dark"));
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(root, { attributes: true, attributeFilter: ["class"] });
    return () => observer.disconnect();
  }, []);

  // Draw the chart at the column's real width, so its text stays 12px instead of shrinking with it.
  useEffect(() => {
    if (!chartBox.current) return undefined;
    const observer = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    observer.observe(chartBox.current);
    return () => observer.disconnect();
  }, []);

  const fmt = (x, places = 0) => x.toLocaleString("en-US", { minimumFractionDigits: places, maximumFractionDigits: places });
  const plural = (n, word) => `${fmt(n)} ${word}${n === 1 ? "" : "s"}`;
  const compact = (x) => (x >= 1000 ? `${+(x / 1000).toFixed(x >= 10000 ? 0 : 1)}K` : String(x));

  // --- results ----------------------------------------------------------------

  const LEVELS = [0.5, 0.95, 0.99]; // service levels on the chart; the last is the plan
  const RANGE = 0.25; // "if your busy hour is 25% quieter or busier"
  const load = loadErlangs(rate, len);
  const levels = LEVELS.map((t) => slotsNeeded(load, t));
  const plan = levels[levels.length - 1];
  const perCall = promiseOverflow(load, plan);
  const [lo, hi] = [1 - RANGE, 1 + RANGE].map((f) => slotsNeeded(load * f, 0.99));
  const rejected = erlangB(load, CAP);
  const pro = proFit(plan, PRO);
  const avgText = fmt(load, load < 10 ? 1 : 0);
  const lenLabel = fmt(len, len % 1 ? 1 : 0);

  // How many calls find every slot in use, on average: calls an hour × the per-call share. It's a
  // long-run average; with long calls it comes in clumps (most busy hours none, a few many).
  const expected = rate * perCall;
  const expectedPhrase = expected >= 1.5 ? `about ${fmt(Math.round(expected))} calls per busy hour`
    : expected >= 0.5 ? "about 1 call per busy hour"
      : Math.round(1 / expected) > 100 ? "fewer than 1 call in 100 busy hours"
        : `about 1 call every ${fmt(Math.round(1 / expected))} busy hours`;
  const rejectedPhrase = rejected >= 0.95 ? "almost every call" : rejected >= 0.095 ? `about ${Math.round(rejected * 10)} in 10 calls`
    : `about ${Math.max(1, Math.round(rejected * 100))} in 100 calls`;

  // --- chart: five simulated busy hours, one highlighted ----------------------

  const W = Math.max(360, width);
  const H = Math.round(Math.min(300, Math.max(230, W * 0.48)));
  const STEP = 0.5, HOURS = 5;
  const narrow = W < 460; // phones: shorter labels, fewer ticks, a shorter readout
  const M = { top: 18, right: narrow ? 124 : W < 560 ? 152 : 176, bottom: 34, left: 44 };
  const hours = Array.from({ length: HOURS }, (_, k) => simulateBusyHour(rate, len, seed * HOURS + k, 60, STEP));
  const main = hours[0].samples;
  const all = hours.flatMap((h) => h.samples);
  const top = Math.max(...all, plan) * 1.03;
  const lo0 = Math.min(...all, levels[0]);
  // Start the axis at zero while the pay-as-you-go limit is in view; for big traffic, zoom to the data.
  const zoom = lo0 > 4 * CAP && lo0 > 40;
  const niceStep = (span) => {
    const raw = span / 5;
    const mag = 10 ** Math.floor(Math.log10(raw));
    return [1, 2, 5, 10].map((m) => m * mag).find((s) => s >= raw);
  };
  const yStep = niceStep(zoom ? top - lo0 * 0.9 : top);
  const yMin = zoom ? Math.floor((lo0 * 0.9) / yStep) * yStep : 0;
  const yMax = Math.ceil(top / yStep) * yStep;
  const plotRight = W - M.right;
  const x = (t) => M.left + (t / 60) * (plotRight - M.left);
  const y = (v) => H - M.bottom - ((v - yMin) / (yMax - yMin)) * (H - M.top - M.bottom);
  const ticks = [];
  for (let v = yMin; v <= yMax + 1e-9; v += yStep) ticks.push(v);
  const path = (s) => s.map((v, i) => `${x(i * STEP)},${y(v)}`).join(" ");
  const clock = (t) => `${Math.floor(t)}:${t % 1 ? "30" : "00"}`;

  // Validated chart colors for light and dark (the brand blue is too light for a data line).
  const C = dark
    ? { series: "#3987e5", grid: "#2e2e33", text: "#f4f4f5", text2: "#d4d4d8", text3: "#a1a1aa", critical: "#e66767", surface: "#0f1117" }
    : { series: "#2a78d6", grid: "#e4e4e7", text: "#18181b", text2: "#52525b", text3: "#71717a", critical: "#d03b3b", surface: "#ffffff" };

  // Line labels in the right margin, top to bottom, at least 15px apart, so they never cross the data.
  // A level at the same value as the pay-as-you-go limit shares its label, with the limit on a second line.
  const capInView = CAP >= yMin;
  const labelList = levels
    .map((v, i) => ({ v, text: i === levels.length - 1 ? (narrow ? "99% plan" : "99% · plan for") : `${LEVELS[i] * 100}%`, strong: i === levels.length - 1 }))
    .filter((l) => l.v >= yMin && l.v <= yMax);
  if (capInView && !labelList.some((l) => l.v === CAP)) labelList.push({ v: CAP, capOnly: true });
  labelList.sort((a, b) => b.v - a.v);
  let next = -Infinity;
  const labels = labelList.map((l) => {
    const ly = Math.max(y(l.v), next);
    const withCap = capInView && l.v === CAP && !l.capOnly;
    next = ly + (withCap ? 29 : 15);
    return { ...l, ly, withCap };
  });

  const full = (h) => h.seen.filter((n) => n >= plan).length;
  const mainFull = full(hours[0]);
  const mainCalls = hours[0].seen.length;
  const allFull = hours.reduce((s, h) => s + full(h), 0);
  const allCalls = hours.reduce((s, h) => s + h.seen.length, 0);
  const summary = `This hour peaked at ${fmt(Math.max(...main))} calls at once, around an average of ${avgText}. `
    + (mainFull === 0
      ? `Every one of its ${fmt(mainCalls)} calls found a free slot among your ${fmt(plan)}. `
      : `${fmt(mainFull)} of its ${fmt(mainCalls)} calls found all ${fmt(plan)} slots in use. `)
    + `Across all ${HOURS} hours, ${fmt(allFull)} of ${fmt(allCalls)} calls (${allCalls ? fmt((allFull / allCalls) * 100, 1) : 0}%) found every slot in use; a 99% service level allows about 1%.`;

  const onPointer = (e) => {
    const box = e.currentTarget.ownerSVGElement.getBoundingClientRect();
    const px = ((e.clientX - box.left) / box.width) * W;
    setHover(Math.min(main.length - 1, Math.max(0, Math.round(((px - M.left) / (plotRight - M.left)) * 60 / STEP))));
  };
  const onKey = (e) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    setHover((h) => Math.min(main.length - 1, Math.max(0, (h ?? -1) + (e.key === "ArrowRight" ? 1 : -1))));
  };
  const others = hover === null ? [] : hours.slice(1).map((h) => h.samples[hover]);
  const tipLeft = hover === null ? 0 : (x(hover * STEP) / W) * 100;
  const tipShift = narrow ? (tipLeft < 50 ? "0" : "-100%") : tipLeft < 20 ? "0" : tipLeft > 65 ? "-100%" : "-50%";

  // --- view ---------------------------------------------------------------------

  const card = "rounded-xl border border-zinc-950/10 dark:border-white/10 p-5 my-4";
  const muted = "text-sm text-zinc-500 dark:text-zinc-400";
  const numberBox = "w-24 rounded-md border border-zinc-950/15 dark:border-white/15 bg-transparent px-2 py-1.5 text-right text-sm";
  const link = "text-primary dark:text-primary-light underline";
  const STATUS = {
    good: { icon: "✓", label: "Fits", bg: "#0ca30c", fg: "#fff" },
    warn: { icon: "!", label: "May fall short", bg: "#fab219", fg: "#3b2a00" },
    bad: { icon: "✕", label: "Too small", bg: "#d03b3b", fg: "#fff" },
    over: { icon: "✕", label: "Likely too small", bg: "#d03b3b", fg: "#fff" },
  };
  const Status = ({ kind }) => (
    <span className="inline-flex items-center gap-1.5 font-semibold">
      <span aria-hidden="true" className="inline-grid h-[18px] w-[18px] place-items-center rounded-full text-xs"
        style={{ background: STATUS[kind].bg, color: STATUS[kind].fg }}>{STATUS[kind].icon}</span>
      {STATUS[kind].label}
    </span>
  );
  const proNote = `No hard cap, but Pro concurrency isn't guaranteed: it depends on system load, and Pro accounts typically get ${PRO[0]}–${PRO[1]} calls at once.`;
  const proText = pro === "fits" ? `${proNote} Your ${plural(plan, "concurrency slot")} fit within that.`
    : pro === "tight" ? `${proNote} Your ${plural(plan, "concurrency slot")} are near the top of that, so you may run short at busy times. For guaranteed capacity, look at Enterprise.`
      : `${proNote} You need ${plural(plan, "concurrency slot")}, more than that. For guaranteed capacity, look at Enterprise.`;

  return (
    <div className="not-prose">
      <div className={card}>
        <div className="grid gap-5">
          <div>
            <label htmlFor="cp-rate" className="mb-2 block font-semibold">Calls in a busy hour</label>
            <div className="flex items-center gap-3">
              <input type="range" min="0" max="1000" aria-label="Calls in a busy hour" className="flex-1" style={{ accentColor: C.series }}
                value={toSlider(rate, RATE)}
                onChange={(e) => { const v = tidyRate(fromSlider(+e.target.value, RATE)); setRate(v); setRateText(String(v)); }} />
              <input id="cp-rate" type="number" min="1" max="100000" className={numberBox} value={rateText}
                onChange={(e) => { setRateText(e.target.value); const v = +e.target.value; if (v >= 1) setRate(v); }} />
            </div>
          </div>
          <div>
            <label htmlFor="cp-len" className="mb-2 block font-semibold">Average call length</label>
            <div className="flex items-center gap-3">
              <input type="range" min="0" max="1000" aria-label="Average call length" className="flex-1" style={{ accentColor: C.series }}
                value={toSlider(len, LEN)}
                onChange={(e) => { const v = tidyLen(fromSlider(+e.target.value, LEN)); setLen(v); setLenText(String(v)); }} />
              <input id="cp-len" type="number" min="0.5" max="60" step="0.5" className={numberBox} value={lenText}
                onChange={(e) => { setLenText(e.target.value); const v = +e.target.value; if (v > 0) setLen(Math.min(v, LEN.max)); }} />
              <span className={muted}>minutes</span>
            </div>
          </div>
        </div>
        <p className={`${muted} mt-4 mb-0`}>
          For calls in a busy hour, think of your busiest hour in a normal week: inbound calls, and outbound calls you place on
          the spot. Running outbound campaigns? Schedule them with the <a className={link} href={OCS_URL}>Outbound Call Scheduler</a>,
          which paces them for you and saves room for incoming calls, so you don't need to count them here. Expecting a launch or
          a big spike? <a className={link} href={SALES} target="_blank" rel="noopener">Talk to us</a>.
        </p>
      </div>

      <div className={card} aria-live="polite">
        <div className="mb-3 text-base font-semibold">What you need</div>
        <div className="grid gap-3">
          <div className="rounded-lg bg-zinc-950/[.03] p-4 dark:bg-white/[.04]">
            <div className={muted}>Calls at once, on average</div>
            <div className="my-1 text-3xl font-semibold">{avgText}</div>
            <div className="text-xs text-zinc-500 dark:text-zinc-400">{fmt(rate)} calls an hour × {lenLabel} min ÷ 60</div>
          </div>
          <div className="rounded-lg bg-zinc-950/[.03] p-4 dark:bg-white/[.04]">
            <div className={muted}>Plan for</div>
            <div className="my-1">
              <span className="text-5xl font-semibold" style={{ color: C.series }}>{fmt(plan)}</span>{" "}
              <span className="text-xl font-semibold">concurrency slots</span>
            </div>
            <div className={muted}>99% service level: room for 99 in 100 calls in your busy hour. One slot is room for one call at a time.</div>
            <div className={`${muted} mt-1`}>On average, {expectedPhrase} would find all {fmt(plan)} in use.</div>
            <div className={`${muted} mt-1`}>If your busy hour is {RANGE * 100}% quieter or busier: {fmt(lo)}–{fmt(hi)} slots.</div>
          </div>
        </div>
        <details className="mt-4">
          <summary className="cursor-pointer text-sm font-semibold" style={{ color: C.series }}>How we get to {fmt(plan)} concurrency slots</summary>
          <ol className="mt-2 list-decimal space-y-1.5 pl-5 text-sm">
            <li>On average, {avgText} calls are active at once: {fmt(rate)} calls an hour × {lenLabel} minutes ÷ 60.</li>
            <li>Calls don't arrive evenly. When each call starts independently of the others, the number active at any moment swings
              around that average (a Poisson distribution), sometimes well above it.</li>
            <li>We find the fewest concurrency slots that leave a free slot for 99 in 100 of the calls that start in your busy hour:{" "}
              <b>{plural(plan, "slot")}</b>, a 99% service level. The other 1 in 100 find every slot in use: at {fmt(rate)} calls an hour,
              that's {expectedPhrase} on average. It comes in clumps, so most busy hours have none and a few have more. At a 50% service
              level you'd need {fmt(levels[0])}, and at 95%, {fmt(levels[1])}.</li>
            <li>Your busy-hour estimate matters most. If it's {RANGE * 100}% lower or higher, you'd need {fmt(lo)} to {fmt(hi)} slots.</li>
          </ol>
          <p className={`${muted} mt-2 mb-0`}>
            <b>Assumptions:</b> the rate you entered holds for the whole hour, calls start independently of each other, and call
            lengths vary around the average you entered. Calls that start together in batches need more: schedule campaigns with the
            Outbound Call Scheduler, and for launches or other spikes, <a className={link} href={SALES} target="_blank" rel="noopener">talk
            to us</a> to plan with your own data.
          </p>
        </details>
      </div>

      <div className={card}>
        <div className="text-base font-semibold">Busy hours, simulated</div>
        <p className={`${muted} mt-1 mb-2`}>
          Calls active at each moment of a random busy hour with your numbers (blue), with four more random hours behind it, against
          your {plural(plan, "concurrency slot")} (99% service level). The 50% and 95% lines show what fewer slots would cover. Each
          run draws new hours.
        </p>
        <div className="mb-1 flex gap-4 text-xs text-zinc-500 dark:text-zinc-400" aria-hidden="true">
          <span className="inline-flex items-center gap-1.5"><span className="inline-block w-4 border-t-2" style={{ borderColor: C.series }} />This hour</span>
          <span className="inline-flex items-center gap-1.5"><span className="inline-block w-4 border-t-2 opacity-50" style={{ borderColor: C.text3 }} />4 more random hours</span>
        </div>
        <div className="relative" ref={chartBox}>
          <svg viewBox={`0 0 ${W} ${H}`} className="block h-auto w-full overflow-visible" tabIndex={0} role="img" onKeyDown={onKey}
            onBlur={() => setHover(null)}
            aria-label={`Simulated busy hours: calls at once every 30 seconds, against ${plan} concurrency slots (99% service level); 50% and 95% levels at ${levels[0]} and ${levels[1]}. This hour peaked at ${Math.max(...main)}.`}>
            {ticks.map((v) => (
              <g key={`t${v}`}>
                <line x1={M.left} x2={plotRight} y1={y(v)} y2={y(v)} stroke={C.grid} strokeWidth={1} />
                <text x={M.left - 8} y={y(v) + 4} textAnchor="end" fontSize={12} fill={C.text3}>{compact(v)}</text>
              </g>
            ))}
            {(narrow ? [0, 30, 60] : [0, 15, 30, 45, 60]).map((t) => (
              <text key={`x${t}`} x={x(t)} y={H - 12} textAnchor={t === 60 ? "end" : "middle"} fontSize={12} fill={C.text3}>{t === 60 ? "60 min" : t}</text>
            ))}
            {levels.map((v, i) => (v < yMin || v > yMax ? null : (
              <line key={`l${i}`} x1={M.left} x2={plotRight} y1={y(v)} y2={y(v)} stroke={i === levels.length - 1 ? C.text : C.text3}
                strokeWidth={i === levels.length - 1 ? 1.5 : 1} strokeOpacity={i === levels.length - 1 ? 0.85 : 0.6} />
            )))}
            {capInView && <line x1={M.left} x2={plotRight} y1={y(CAP)} y2={y(CAP)} stroke={C.critical} strokeWidth={1.5} strokeDasharray="5 4" />}
            {hours.slice(1).map((h, k) => (
              <polyline key={`h${k}`} points={path(h.samples)} fill="none" stroke={C.text3} strokeOpacity={0.35} strokeWidth={1.25} strokeLinejoin="round" />
            ))}
            <polyline points={path(main)} fill="none" stroke={C.series} strokeWidth={2} strokeLinejoin="round" strokeLinecap="round" />
            {labels.map((l) => (
              <g key={`lab${l.v}`}>
                {l.capOnly ? (
                  <>
                    <line x1={plotRight + 10} x2={plotRight + 22} y1={l.ly} y2={l.ly} stroke={C.critical} strokeWidth={1.5} strokeDasharray="5 4" />
                    <text x={plotRight + 28} y={l.ly + 4} fontSize={12} fill={C.text2}>
                      <tspan fontWeight={700} fill={C.text}>{fmt(l.v)} </tspan>{narrow ? "pay as you go" : "pay as you go limit"}
                    </text>
                  </>
                ) : (
                  <>
                    <text x={plotRight + 10} y={l.ly + 4} fontSize={12} fill={C.text2}>
                      <tspan fontWeight={700} fill={C.text}>{narrow ? `${fmt(l.v)} · ` : `${plural(l.v, "slot")} `}</tspan>
                      <tspan fontWeight={l.strong ? 600 : 400}>{l.text}</tspan>
                    </text>
                    {l.withCap && (
                      <>
                        <line x1={plotRight + 10} x2={plotRight + 22} y1={l.ly + 14} y2={l.ly + 14} stroke={C.critical} strokeWidth={1.5} strokeDasharray="5 4" />
                        <text x={plotRight + 28} y={l.ly + 18} fontSize={12} fill={C.text2}>{narrow ? "pay as you go" : "pay as you go limit"}</text>
                      </>
                    )}
                  </>
                )}
              </g>
            ))}
            {hover !== null && (
              <>
                <line x1={x(hover * STEP)} x2={x(hover * STEP)} y1={M.top} y2={H - M.bottom} stroke={C.text3} strokeWidth={1} />
                <circle cx={x(hover * STEP)} cy={y(main[hover])} r={4.5} fill={C.series} stroke={C.surface} strokeWidth={2} />
              </>
            )}
            <rect x={M.left} y={M.top} width={plotRight - M.left} height={H - M.top - M.bottom} fill="transparent"
              onPointerMove={onPointer} onPointerLeave={() => setHover(null)} />
          </svg>
          {hover !== null && (
            <div className="pointer-events-none absolute whitespace-nowrap rounded-md border border-zinc-950/10 bg-white px-2.5 py-1.5 text-xs shadow-sm dark:border-white/10 dark:bg-zinc-900"
              style={{ left: `${tipLeft}%`, top: `${(y(main[hover]) / H) * 100}%`,
                transform: `translate(${tipShift}, calc(-100% - 12px))` }}>
              <b className="text-sm">{fmt(main[hover])}</b>
              <span className="text-zinc-500 dark:text-zinc-400">
                {narrow ? ` at ${clock(hover * STEP)}, others ${fmt(Math.min(...others))}–${fmt(Math.max(...others))}`
                  : ` calls at once at ${clock(hover * STEP)} (other hours: ${fmt(Math.min(...others))}–${fmt(Math.max(...others))})`}
              </span>
            </div>
          )}
        </div>
        <p className={`${muted} mt-4 mb-2`}>{summary}</p>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <details className="text-xs">
            <summary className="cursor-pointer text-zinc-500 dark:text-zinc-400">Show this hour as a table</summary>
            <table className="mt-2 w-full text-sm">
              <thead><tr><th className="py-1 text-left">Time</th><th className="py-1 text-right">Calls at once</th></tr></thead>
              <tbody>{main.map((v, i) => <tr key={i}><td className="py-0.5">{clock(i * STEP)}</td><td className="py-0.5 text-right">{fmt(v)}</td></tr>)}</tbody>
            </table>
          </details>
          <button type="button" onClick={() => setSeed((s) => s + 1)}
            className="rounded-md border border-zinc-950/15 px-3 py-1.5 text-sm dark:border-white/15">↻ Run again</button>
        </div>
      </div>

      <div className={card}>
        <div className="mb-1 text-base font-semibold">Which plan fits</div>
        <div className="divide-y divide-zinc-950/10 dark:divide-white/10">
          <div className="grid gap-1 py-3 sm:grid-cols-[150px_1fr] sm:gap-4">
            <div><div className="font-semibold">Pay as you go</div><div className={muted}>Up to {CAP} concurrency slots</div></div>
            <div>
              <Status kind={rejected <= 0.01 ? "good" : "bad"} />
              <div className={muted}>{rejected <= 0.01 ? `Your busy hour fits in ${CAP} slots.`
                : `You need ${plural(plan, "concurrency slot")}. With ${CAP}, ${rejectedPhrase} in your busy hour would be turned away.`}</div>
            </div>
          </div>
          <div className="grid gap-1 py-3 sm:grid-cols-[150px_1fr] sm:gap-4">
            <div><div className="font-semibold">Pro</div><div className={muted}>No hard cap</div></div>
            <div>
              <Status kind={pro === "fits" ? "good" : pro === "tight" ? "warn" : "over"} />
              <div className={muted}>{proText}</div>
            </div>
          </div>
          <div className="grid gap-1 py-3 sm:grid-cols-[150px_1fr] sm:gap-4">
            <div><div className="font-semibold">Enterprise</div><div className={muted}>Priority capacity</div></div>
            <div>
              <div className="text-sm">Reserve your {plural(plan, "concurrency slot")} as guaranteed priority capacity, sized with our team.</div>
              <a href={SALES} target="_blank" rel="noopener"
                className="mt-2 inline-block whitespace-nowrap rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white no-underline">Talk to sales</a>
            </div>
          </div>
        </div>
      </div>

      <p className={`${muted} mb-0`}>
        These are estimates: they assume calls start independently of each other at a steady rate through the hour. Real traffic varies,
        so talk to us to plan with your own data. See <a className={link} href="#priority-concurrency">Priority Concurrency</a> and{" "}
        <a className={link} href="#hard-concurrency-caps">Hard Concurrency Caps</a> for how each limit works.
      </p>
    </div>
  );
};
